    spDescTeamUp: 'ওয়ালেট পাওয়ারকে আরও সাতটি অ্যাকাউন্টের সাথে সংযুক্ত করুন । দলের প্রত্যেকে পুল করা ব্যালেন্স আনলক করে ব্যাজ পরেন এবং এতে কোনও খরচ হয় না । একটি দল ব্যক্তিগত হতে পারে, তাই লোকেরা যোগ দিতে বলে এবং মালিক তাদের অনুমোদন করে ।',
