    affiliateB1Desc: 'প্রতিটি অ্যাকাউন্টে একটি অনন্য রেফারেল লিঙ্ক এবং কোড থাকে যা আপনি ছোট /r/ লিঙ্ক সহ যে কোনও জায়গায় শেয়ার করতে পারেন । একটি রেফারেল লিঙ্ক DeHub-এর যে কোনও পৃষ্ঠায় নির্দেশ করতে পারে, একটি আমন্ত্রণ পৃষ্ঠা বেশ কয়েকটি গন্তব্যস্থল সরবরাহ করতে পারে এবং আপনার শেয়ার করা ব্লগ নিবন্ধগুলি স্বয়ংক্রিয়ভাবে আপনার লিঙ্কটি বহন করে ।',
    affiliateB3Desc: 'অ্যাফিলিয়েট ড্যাশবোর্ড আপনার ক্লিক, সাইনআপ এবং উপার্জন দেখায় এবং আপনাকে আপনার আমন্ত্রণ পৃষ্ঠা এবং এর শেয়ারের চিত্রটি কাস্টমাইজ করতে দেয় । আপনার নিজের ভিজিট গণনা করা হয় না ।',
