    miniAppsB2: 'ফিডে শেয়ার করুন:',
    miniAppsB2Desc: 'অ্যাপগুলি সুরকারকে খুলতে পারে, প্রোফাইল এবং পোস্টগুলি দেখাতে পারে এবং ফিডে একটি অ্যাপের লিঙ্ক কার্ড হিসাবে একটি বোতাম হিসাবে দেখাতে পারে যা এটি জায়গায় খোলে ।',
