    govLiveDesc: 'উপরের নকশাটি হ \'ল গভর্নেন্সের জন্য; গভর্নেন্স পৃষ্ঠাটি যেখানে এটি ঘটে । প্রস্তাবগুলি প্রস্তাবের অধীনে তালিকাভুক্ত করা হয়, পাস করা হয় এবং প্রত্যাখ্যান করা হয়, প্রত্যেকে তার লেখক, তার পাঠ্য এবং যেখানে ভোটটি দাঁড়িয়ে আছে । একটি প্রস্তাব খোলার জন্য 10,000 DeHub টোকেনের ফি লাগে, যা শৃঙ্খলে নিশ্চিত করা হয় এবং প্রতিটি প্রস্তাবের একটি থ্রেডেড আলোচনা সহ নিজস্ব পৃষ্ঠা থাকে । ভোট দেওয়া বিনামূল্যে: আপনার ভোটটি আপনার ব্যাজ দ্বারা ওজন করা হয়, সাত দিনের জন্য ভোট দেওয়া হয় এবং কমপক্ষে দশটি ভিন্ন ওয়ালেট ভোট দিয়ে একটি ওজনযুক্ত সংখ্যাগরিষ্ঠতার সাথে একটি প্রস্তাব পাস হয়, তাই কোনও একক ধারক এমন কিছু পাস করতে পারে না যা কেউ দেখেনি ।',
