    aiSuiteB1Desc: 'একটি চ্যাট সহকারী যা DeHub সম্পর্কে প্রশ্নের উত্তর দেয়, পোস্টার এবং মার্কেটিং সম্পদ তৈরি করে এবং আপনাকে বিষয়বস্তু পরিকল্পনা এবং তৈরি করতে সহায়তা করে ।',
