    aiSuiteDesc: 'DeHub নির্মাতাদের জন্য AI সরঞ্জামগুলির একটি সম্পূর্ণ সেট বান্ডিল করে, সমস্ত অ্যাপের ভিতরে কোনও বাহ্যিক অ্যাকাউন্ট বা API কী ছাড়াই উপলব্ধ । স্যুটটিতে একটি কথোপকথন সহকারী, স্বায়ত্তশাসিত এজেন্ট এবং একটি নো-কোড অ্যাপ বিল্ডার রয়েছে, যাতে আপনি প্ল্যাটফর্ম ত্যাগ না করে একটি ধারণা থেকে উত্পন্ন সামগ্রী বা একটি কার্যকরী মিনি অ্যাপে যেতে পারেন ।',
    allowanceCounts1: 'শুধুমাত্র পাঠ্য-পুস্তক পোস্টগুলি আপনার প্রতিদিনের একটি করে টেক্সট পোস্টে ব্যয় করে ।',
