    allowanceCounts3: 'কোটেশন পোস্টের সংখ্যা মূল পোস্টের মতোই গণনা হয়: একটি ভিডিও সংযুক্ত কোটেশনও ডেটা খরচ করে।',
    allowanceCounts4: 'গড়টি প্রো-রাটা, পুরো গিগাবাইট পর্যন্ত বৃত্তাকার নয় । যদি 200 মেগাবাইটের আপলোড আপনার ভাতা ছাড়িয়ে যায়, তাহলে আপনি 200 মেগাবাইটের জন্য অর্থ প্রদান করবেন ।',
    allowanceCounts5: 'পুনরায় পোস্ট, মন্তব্য, প্রতিক্রিয়া, পরামর্শ এবং বার্তাগুলির কোনও মূল্য নেই এবং কখনই ভাতাটি স্পর্শ করবেন না ।',
    allowanceCountsTitle: 'এর বিরুদ্ধে কী গুরুত্ব বহন করে',
    allowanceHowTitle: 'কীভাবে পেমেন্ট কাজ করে',
    allowanceIntro: 'DeHub-এ পোস্ট করা প্রতিদিন বিনামূল্যে, আপনার স্ট্যাকিং ব্যাজের সাথে স্কেল করা ভাতা পর্যন্ত । প্রত্যেকে প্রতিদিন দশটি টেক্সট পোস্ট এবং এক গিগাবাইট ভিডিও, ছবি এবং অডিও দিয়ে শুরু করে । ডেহাব টোকেনগুলিতে সেই দিনের বাকি অংশের জন্য অর্থ প্রদান করা হয় — 10c একটি টেক্সট পোস্ট, $ 2 প্রতি গিগাবাইট, শুধুমাত্র যে অংশে চলছে তার উপর চার্জ করা হয় ।',
