    spPowersLead: 'ব্যাজ মইয়ের প্রতিটি রান ঠিক একটি পাওয়ার আনলক করে এবং আপনার আনলক করা প্রতিটি পাওয়ার আনলক থাকে । তারা সবাই একই পাক্ষিক ভাতার উপর আঁকেন, তাই এটি কী ব্যয় করতে হবে তা বেছে নেওয়া হয় ।',
    spRotationDesc: 'পিনের পরিবর্তে স্লটটি ঘুরছে । যখন বেশ কয়েকটি বুস্ট একসাথে চলছে, প্রতিটি দর্শককে বুস্টারের ব্যাজ স্তর দ্বারা ওজন করা হয় — একটি উচ্চতর স্তর প্রায়শই দেখানো হয় এবং প্রত্যেকে এখনও তাদের দেওয়া উইন্ডোটি পায় । একটি বুস্ট কেনা একটি নির্দিষ্ট সংখ্যক মিনিটের জন্য ভয়েস শেয়ার, ফিডের শীর্ষের একমাত্র দখল নয় ।',
    spRotationTitle: 'স্লটটি কীভাবে শেয়ার করা হয়',
    spSafetyDesc: 'প্রতিটি ড্র সেই মুহুর্তে দাঁড়িয়ে থাকার কারণে পোস্টের বিরুদ্ধে পুনরায় চেক করা হয়, তাই এমন একটি পোস্ট যা তখন থেকে সরানো, অবরুদ্ধ বা চিহ্নিত পরিপক্ক কখনও কোনও অপরিচিতের ফিডে পৌঁছায় না । পরিপক্ক পোস্টগুলিও বুকিংয়ে প্রত্যাখ্যান করা হয় এবং আপনাকে বা আপনি যে ব্যক্তিকে বুস্ট করেছেন তাকে কখনও কোনও বুস্ট দেওয়া হয় না ।',
    spSafetyTitle: 'একটি বুস্ট কি করতে পারে না',
