    accountsB5: 'নতুন সদস্য:',
    allowanceIntro2: 'টেক্সট পোস্ট এবং মিডিয়া আলাদা পুল । একটির বাইরে চলে যাওয়া অন্যটিকে স্পর্শ করে না, তাই ভিডিও আপলোড করার জন্য ব্যয় করা একটি দিন এখনও সমস্ত দশটি পাঠ্য পোস্ট বিনামূল্যে ছেড়ে দেয় । উভয়ই মধ্যরাত্রি ইউটিসি-তে রিসেট করুন ।',
    allowanceHowDesc: 'অর্ডারটি গুরুত্বপূর্ণ, এবং এটি ইচ্ছাকৃত: এমন কোনও পোস্টের জন্য আপনাকে কখনই চার্জ করা হয় না যা প্রকাশ করা হয়নি এবং আপনি কখনই একটি বড় ফাইল আপলোড করবেন না শুধুমাত্র পরে বলা হবে যে আপনি এর জন্য অর্থ প্রদান করতে পারবেন না ।',
    allowanceStep1: 'অ্যাপটি আপনি আজ যা পোস্ট করেছেন তার বিপরীতে মূল্য পরীক্ষা করে এবং নিশ্চিত করে যে আপনার ওয়ালেট এটি কভার করতে পারে । কিছুই চার্জ করা হয় না এবং এটি শেষ না হওয়া পর্যন্ত কিছুই আপলোড করা হয় না ।',
    allowanceStep2: 'আপনার পোস্টটি ঠিক যেমনটি বিনামূল্যে ভাতার মধ্যে থাকবে ঠিক তেমনই লাইভ হবে । প্রকাশনা কখনই পেমেন্টের জন্য অপেক্ষা করে না ।',
    allowanceBadgeNote: 'একটি ব্যাজ একবারে উভয় অর্ধেকে চলে যায় — একটি বৃহত্তর বিনামূল্যে ভাতা এবং এর আগের যে কোনও কিছুর চেয়ে কম দাম । ডিহাব টোকেন কেনার সময় ডিসকাউন্টটি ইতিমধ্যে একই মই ব্যাজ হোল্ডার, ক্র্যাবে 5% থেকে মেগালডনে 30% পর্যন্ত, তাই ব্যাজটির মূল্য কী তার একটি উত্তর রয়েছে । আপনার ভাতা আপনার অর্জিত ব্যাজ থেকে আসে: আপনার প্রোফাইলে একজন পৃষ্ঠপোষক শো দ্বারা আপনাকে ধার দেওয়া একটি স্তর, কিন্তু এটি আপনাকে তাদের পোস্টিং ভাতা প্রদান করে না ।',
    badgePriceTitle: 'মইটির দাম ডলারে নির্ধারণ করা হয়েছে',
    badgeUnlock3: 'ডেহাব টোকেন কেনার সময় একই ডিসকাউন্ট, ক্র্যাবে ৫ % থেকে মেগালডনে ৩০ % পর্যন্ত ।',
    badgeDelegationB1: 'একই স্তর, নীচে একটি নয়:',
    badgeDelegationB1Desc: 'একটি মেগালডন মেগালডনকে ধার দেয় । একটি ব্যাজ আপনার আদেশের প্রভাব দাবি করে, তাই আপনি ফিরে আসা লোকেরা আপনার যা বহন করে তা বহন করে ।',
    badgeDelegationB3Desc: 'অ্যাপের যে কোনও জায়গায় একটি অর্পিত ব্যাজ রাখুন এবং এটি কে সমর্থন করছে তার নাম দিন । একটি স্তর কোথা থেকে এসেছে সে সম্পর্কে কিছুই লুকানো নেই ।',
    badgeDelegationB4: 'যে কোনও সময় বিপরীতমুখী:',
    badgeDelegationB6Desc: 'একটি স্লটকে আপনার শীর্ষ স্তরটি হস্তান্তর করতে হবে না । এটি যে আনলকড রানটি ধার দেয় তা বেছে নিন এবং মেগালডন না করে কিং কোবরাতে কাউকে ফিরিয়ে দিন ।',
