    feedsTranslateDesc: 'আপনি স্ক্রোল করার সাথে সাথে পোস্ট এবং মন্তব্যগুলি আপনার ভাষায় অনুবাদ করে, একশটিরও বেশি ভাষায়, কোনও ওয়ালেট সংযোগ নেই এবং খুঁজে পাওয়ার জন্য কোনও সেটিংস নেই । যে কোনও সময় মূলটিতে ট্যাপ করুন ।',
    communitiesDesc2: 'ইভেন্টগুলি সময়সীমার প্রোগ্রামিং সহ সম্প্রদায়গুলিকে প্রসারিত করে । একটি সম্প্রদায় বা প্ল্যাটফর্ম একটি ইভেন্ট নির্ধারণ করতে পারে, সম্পূর্ণ বিবরণ সহ একটি ডেডিকেটেড ইভেন্ট পৃষ্ঠা প্রকাশ করতে পারে এবং এটি শুরু হওয়ার সাথে সাথে সদস্যদের লাইভ অনুসরণ করতে দেয় । একসাথে, সম্প্রদায় এবং ইভেন্টগুলি ইকোসিস্টেমকে একটি ভাগ করা আগ্রহের চারপাশে সংগঠিত করার এবং মানুষকে ফিরে আসতে রাখার সরঞ্জাম দেয় ।',
    communitiesB2: 'কমিউনিটি ফিড:',
    communitiesB3: 'ইভেন্টসমূহ:',
    communitiesB3Desc: 'প্ল্যাটফর্ম এবং কমিউনিটি ইভেন্টগুলি ব্রাউজ করুন, সম্পূর্ণ এজেন্ডা এবং বিশদ বিবরণের জন্য একটি ইভেন্ট পৃষ্ঠা খুলুন এবং ইভেন্টটি শুরু হওয়ার পরে লাইভ অনুসরণ করুন ।',
    stagesDesc2: 'DeHub স্টেজকে আলাদা করে যা সেট করে তা হল প্রোডাকশন লেয়ার । হোস্টগুলি একটি ডিজে-স্টাইল সাউন্ডবোর্ড পায় যা সাউন্ড এফেক্ট, তাদের নিজস্ব মিউজিক ক্লিপ এবং লাইভ রেডিও স্টেশনগুলিকে প্রকাশিত রুম অডিওতে মিশ্রিত করে, পাশাপাশি ভয়েস এফেক্টগুলি, যাতে একটি মঞ্চ একটি কনফারেন্স কলের পরিবর্তে একটি উত্পাদিত শোয়ের মতো অনুভব করতে পারে । হোস্টরা তাদের স্ক্রিন শেয়ার করতে পারে, কোনও ওবিএস বা স্ট্রিম কী ছাড়াই ব্রাউজার থেকে পুরো জিনিসটি চালাতে পারে এবং আগে থেকে একটি রুম নির্ধারণ করতে পারে যাতে কোনও শ্রোতা দরজা খোলার আগে অপেক্ষা করে ।',
    stagesDesc3: 'ঘরটিও পাঠযোগ্য । লাইভ সাবটাইটেল ক্যাপশন প্রতিটি বক্তা যখন কথা বলে এবং প্রতিটি শ্রোতা যে ভাষায় পড়ছেন সে ভাষায় অনুবাদ করা হয়, তাই মঞ্চে কেউ কথা বলে না এমন ভাষায় একটি পর্যায় অনুসরণ করা যেতে পারে । লাইভ ডাবিং আরও এক ধাপ এগিয়ে যায় এবং হোস্টের নিজস্ব ক্লোনকৃত কণ্ঠে ঘরটি উচ্চস্বরে কথা বলে, DeHub টোকেনে মিনিটের মধ্যে বিল করা হয় । একটি লাইভ ট্রান্সক্রিপ্ট ড্রয়ার এবং টেক্সট-টু-স্পিচ মাইক্রোফোন ছাড়াই কক্ষগুলি ব্যবহারযোগ্য রাখে এবং একটি স্থায়ী কোণার মিনি-প্লেয়ার আপনাকে স্টেজ প্লে করার সময় অ্যাপের বাকি অংশ ব্রাউজ করতে দেয় ।',
    stagesB1: 'হোস্ট এবং স্পিক:',
    stagesB1Desc: 'একটি পর্যায় শুরু করুন, পর্যায়ক্রমে স্পিকারদের আমন্ত্রণ জানান, অংশগ্রহণকারীদের নিঃশব্দ করুন বা সরান এবং হোস্ট কন্ট্রোল থেকে রিয়েল টাইমে রুম পরিচালনা করুন ।',
