    stagesB5: 'সময়সূচী এবং মনে করিয়ে দিন:',
    stagesB5Desc: 'একটি সংক্ষিপ্ত আমন্ত্রণ লিঙ্ক এবং এর নিজস্ব শেয়ার কার্ড সহ সময়ের আগে একটি পর্যায় ঘোষণা করুন । রিমাইন্ডার সেট করা প্রত্যেককে সতর্ক করা হয় যখন এটি শুরু হতে চলেছে, এবং আবার যখন এটি লাইভ হয়ে যায় ।',
