    prereq2: 'গুগল, অ্যাপল বা টেলিগ্রাম অ্যাকাউন্ট, একটি ইমেইল ঠিকানা, একটি ফোন নম্বর বা একটি পাসকি — অথবা আপনি ইতিমধ্যে ব্যবহার করছেন এমন একটি ওয়ালেট',
    prereq3: 'আর কিছুই নয়: কোন সিড ফ্রেজ লিখতে হবে না এবং কোন গ্যাস কিনতে হবে না',
    step1Title: 'আপনার অ্যাকাউন্ট তৈরি করুন',
    step1Desc: 'ডিহাব.আই খুলুন এবং সাইন ইন ট্যাপ করুন। গুগল, অ্যাপল, টেলিগ্রাম, ইমেইল, এসএমএস, একটি পাসকি বা একটি ওয়ালেট নির্বাচন করুন। আপনার পিছনে একটি নন-কাস্টডিয়াল ওয়ালেট তৈরি হয় — আপনি কীগুলি ধরে রাখেন — এবং গ্যাস স্পন্সর করা হয়, তাই শুরু করার আগে কিছুই ফান্ড করতে হবে না।',
    step2Title: 'আপনার প্রোফাইল সেট আপ করুন',
    step2Desc: 'সেটিংস → প্রোফাইল এ একটি ডিসপ্লে নাম, ইউজারনেম, অ্যাভাটার, কভার ইমেজ এবং বায়ো যোগ করুন এবং আপনার অন্যান্য সোশ্যাল লিঙ্ক করুন যাতে আপনার প্রোফাইল আপনার সম্পূর্ণ রিচ দেখায়। সেটিংস → অ্যাপিয়ারেন্স এ একটি থিম নির্বাচন করুন যখন আপনি সেখানে থাকবেন, এবং যদি আপনি চান তাহলে অপশনাল গাইডেড ওয়াকথ্রু নিন যাতে আপনাকে দেখানো হয়।',
    step3Title: 'আপনার প্রথম পোস্ট তৈরি করুন',
    step3Desc: 'ট্যাপ করুন ক্রিয়েট। একটি পোস্ট লিখুন, ছবি, ভিডিও বা অডিও যোগ করুন, লং-ফর্ম লেখার জন্য আর্টিকেলে পরিবর্তন করুন, বা লাইভ যান। দৈনিক অনুমতি পর্যন্ত পোস্টিং ফ্রি — দশটি টেক্সট পোস্ট এবং একটি ডিবি মিডিয়া প্রতিদিন ব্যাডজ ছাড়া। একটি পোস্ট অন-চেইন মিন্ট করা অপশনাল এবং পরে করা যেতে পারে।',
    step4Title: 'আপনার অডিয়েন্স থেকে আয়ের জন্য',
    step4Desc: 'প্রতিটি পোস্ট ডিহাব টোকেন দিয়ে টিপ করা যেতে পারে। তারপর থেকে আপনি সাবস্ক্রিপশন বিক্রি করতে পারেন, পে-পার-ভিউ পোস্ট প্রকাশ করতে পারেন, ডাইরেক্ট মেসেজের জন্য মিনিমাম টিপ সেট করতে পারেন, একটি স্টোর খুলতে পারেন, বাউন্টি পোস্ট করতে পারেন এবং আপনার অ্যাফিলিয়েট লিঙ্ক শেয়ার করতে পারেন যাতে আপনি আপনার সাথে আনা লোকদের থেকে আয়ের জন্য।',
    step5Title: 'টোকেন ধরে রাখুন একটি ব্যাডজ পেতে',
    step5Desc: 'ডিহাব টোকেন ধরে রাখা বা স্টেকিং একটি ব্যাডজ অর্জন করে, ক্রাব থেকে মেগালোডন পর্যন্ত। একটি ব্যাডজ আপনার ফি কমায়, পোস্টিং অনুমতি বাড়ায়, সুপারপাওয়ারস আনলক করে এবং আপনার ভিউ, রিয়াকশন এবং ভোটের ওজন বাড়ায়।',
    step6Title: 'আপনার ওয়ালেট ব্যবহার করুন',
    step6Desc: 'আপনার ওয়ালেটে বিভিন্ন চেইন জুড়ে DeHub টোকেন এবং অন্যান্য ক্রিপ্টো রয়েছে । কার্ডের মাধ্যমে বা $ 0.50 থেকে ক্রিপ্টো দিয়ে টোকেন কিনুন, বিনামূল্যে যে কাউকে পাঠান, DeHub এক্সচেঞ্জে ট্রেড করুন এবং ব্যাজ মইতে আরোহণের জন্য শেয়ার করুন ।',
    congratulations: '🎉 আপনি সেট আপ করেছেন',
    congratulationsDesc: 'আপনার কাছে একটি অ্যাকাউন্ট, একটি প্রোফাইল এবং একটি প্রথম পোস্ট আছে। দ্য ডি অ্যাপ গাইড আপনি অ্যাপটি আর কীভাবে ব্যবহার করতে পারেন সে সম্পর্কে সবকিছু কভার করে।',
